template <typename UnionPtrType>
IppAttributeValuePtr IppAttributeValue::Clone() const {
  switch (tag_) {
    case Tag::kBools:
      return NewBools(
          mojo::Clone(*data_.bools));
    case Tag::kDate:
      return NewDate(
          mojo::Clone(*data_.date));
    case Tag::kInts:
      return NewInts(
          mojo::Clone(*data_.ints));
    case Tag::kStrings:
      return NewStrings(
          mojo::Clone(*data_.strings));
    case Tag::kOctets:
      return NewOctets(
          mojo::Clone(*data_.octets));
    case Tag::kResolutions:
      return NewResolutions(
          mojo::Clone(*data_.resolutions));
  }
  return nullptr;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, IppAttributeValue>::value>::type*>
bool IppAttributeValue::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kBools:
      return mojo::Equals(*(data_.bools), *(other.data_.bools));
    case Tag::kDate:
      return mojo::Equals(*(data_.date), *(other.data_.date));
    case Tag::kInts:
      return mojo::Equals(*(data_.ints), *(other.data_.ints));
    case Tag::kStrings:
      return mojo::Equals(*(data_.strings), *(other.data_.strings));
    case Tag::kOctets:
      return mojo::Equals(*(data_.octets), *(other.data_.octets));
    case Tag::kResolutions:
      return mojo::Equals(*(data_.resolutions), *(other.data_.resolutions));
  }

  return false;
}
